#pragma once
// The Material Symbols icons that are built into the program (IconFontData.cpp, generated by tools/subset-material-symbols.py).
#include <cstddef>

namespace vkui {

struct EmbeddedIconFont { const unsigned char* data; std::size_t size; };

/// Style 1 = Outlined, 2 = Rounded, 3 = Sharp (as IconStyle). {nullptr, 0} for anything else.
const EmbeddedIconFont& embeddedIconFont(int style);

}  // namespace vkui
